styles:
.rog-post-container {
            width: 100%;
            max-width: 100%;
        }
        .rog-post-container img {
            max-width: 100% !important;
            height: auto !important;
            display: block;
            margin: 25px auto;
            border-radius: 4px;
        }
        .rog-post-container a {
            color: #ff3333 !important;
            text-decoration: none;
            font-weight: bold;
        }
        .rog-post-container a:hover {
            text-decoration: underline;
            color: #ff0000 !important;
        }
        .rog-post-container h2 {
            color: #ffffff !important;
            border-left: 5px solid #cc0000;
            padding-left: 15px;
            margin-top: 40px;
            margin-bottom: 20px;
            text-transform: uppercase;
            font-weight: 700;
            font-size: 1.8em;
        }
        .rog-post-container p {
            color: #ffffff !important;
            margin-bottom: 20px;
        }
        .rog-post-container ul {
            margin-left: 20px;
            margin-bottom: 20px;
            color: #ffffff;
        }
        .rog-post-container li {
            margin-bottom: 10px;
        }
        .rog-post-container strong {
            color: #ffffff;
            font-weight: bold;
        }
